    // 以下の CORS 設定を特定の要件に合わせて修正してください\n    headers: {\n      "Access-Control-Allow-Origin": "*", // これを信頼できるドメインに制限してください\n      "Access-Control-Allow-Headers": "*", // 許可する必要があるヘッダーのみを指定してください\n    },\n    body: JSON.stringify("Hello from api-function!"),\n  };\n};\n'})}),"\n",(0,a.jsx)(t.p,{children:"次に、AWS CDK を使用して、バックエンドファイルに HTTP API を作成します："}),"\n",(0,a.jsx)(t.pre,{title:"amplify/backend.ts",children:(0,a.jsx)(t.code,{className:"language-ts",children:'import { defineBackend } from "@aws-amplify/backend";\nimport { Stack } from "aws-cdk-lib";\nimport {\n  CorsHttpMethod,\n  HttpApi,\n  HttpMethod,\n} from "aws-cdk-lib/aws-apigatewayv2";\nimport {\n  HttpIamAuthorizer,\n  HttpUserPoolAuthorizer,\n} from "aws-cdk-lib/aws-apigatewayv2-authorizers";\nimport { HttpLambdaIntegration } from "aws-cdk-lib/aws-apigatewayv2-integrations";\nimport { Policy, PolicyStatement } from "aws-cdk-lib/aws-iam";\nimport { myApiFunction } from "./functions/api-function/resource";\nimport { auth } from "./auth/resource";\nimport { data } from "./data/resource";\n\nconst backend = defineBackend({\n  auth,\n  data,\n  myApiFunction,\n});\n\n// 新しい API スタックを作成する\nconst apiStack = backend.createStack("api-stack");\n\n// IAM オーソライザーを作成する\nconst iamAuthorizer = new HttpIamAuthorizer();\n\n// ユーザープール オーソライザーを作成する\nconst userPoolAuthorizer = new HttpUserPoolAuthorizer(\n  "userPoolAuth",\n  backend.auth.resources.userPool,\n  {\n    userPoolClients: [backend.auth.resources.userPoolClient],\n  }\n);\n\n// 新しい HTTP Lambda インテグレーションを作成する\nconst httpLambdaIntegration = new HttpLambdaIntegration(\n  "LambdaIntegration",\n  backend.myApiFunction.resources.lambda\n);\n\n// IAM をデフォルトオーソライザーとした新しい HTTP API を作成する\nconst httpApi = new HttpApi(apiStack, "HttpApi", {\n  apiName: "myHttpApi",\n  corsPreflight: {\n    // 以下の CORS 設定を特定の要件に合わせて修正してください\n    allowMethods: [\n      CorsHttpMethod.GET,\n      CorsHttpMethod.POST,\n      CorsHttpMethod.PUT,\n      CorsHttpMethod.DELETE,\n    ],\n    // これを信頼できるドメインに制限してください\n    allowOrigins: ["*"],\n    // 許可する必要があるヘッダーのみを指定してください\n    allowHeaders: ["*"],\n  },\n  createDefaultStage: true,\n});\n\n// IAM オーソライザーとさまざまなメソッドを使用して API にルートを追加する\nhttpApi.addRoutes({\n  path: "/items",\n  methods: [HttpMethod.GET, HttpMethod.PUT, HttpMethod.POST, HttpMethod.DELETE],\n  integration: httpLambdaIntegration,\n  authorizer: iamAuthorizer,\n});\n\n// API にプロキシリソースパスを追加する\nhttpApi.addRoutes({\n  path: "/items/{proxy+}",\n  methods: [HttpMethod.ANY],\n  integration: httpLambdaIntegration,\n  authorizer: iamAuthorizer,\n});\n\n// ルートに OPTIONS メソッドを追加する\nhttpApi.addRoutes({\n  path: "/items/{proxy+}",\n  methods: [HttpMethod.OPTIONS],\n  integration: httpLambdaIntegration,\n});\n\n// ユーザープール オーソライザーを使用してルートを API に追加する\nhttpApi.addRoutes({\n  path: "/cognito-auth-path",\n  methods: [HttpMethod.GET],\n  integration: httpLambdaIntegration,\n  authorizer: userPoolAuthorizer,\n});\n\n// API への Invoke アクセスを許可する新しい IAM ポリシーを作成する\nconst apiPolicy = new Policy(apiStack, "ApiPolicy", {\n  statements: [\n    new PolicyStatement({\n      actions: ["execute-api:Invoke"],\n      resources: [\n        `${httpApi.arnForExecuteApi("*", "/items")}`,\n        `${httpApi.arnForExecuteApi("*", "/items/*")}`,\n        `${httpApi.arnForExecuteApi("*", "/cognito-auth-path")}`,\n      ],\n    }),\n  ],\n});\n\n// ポリシーを認証済みおよび未認証 IAM ロールにアタッチする\nbackend.auth.resources.authenticatedUserIamRole.attachInlinePolicy(apiPolicy);\nbackend.auth.resources.unauthenticatedUserIamRole.attachInlinePolicy(apiPolicy);\n\n// 出力を設定ファイルに追加する\nbackend.addOutput({\n  custom: {\n    API: {\n      [httpApi.httpApiName!]: {\n        endpoint: httpApi.url,\n        region: Stack.of(httpApi).region,\n        apiName: httpApi.httpApiName,\n      },\n    },\n  },\n});\n'})}),"\n",(0,a.jsx)(t.h2,{id:"amplify-ライブラリをインストールする",children:"Amplify ライブラリをインストールする"}),"\n",(0,a.jsxs)(n,{filters:["javascript","angular","react","vue","react-native","nextjs"],children:[(0,a.jsxs)(t.p,{children:["任意の